$conn->set_charset('utf8mb4');
$is_mentor=admin_is_mentor(); $can_manage_events=!$is_mentor;
$filter_status=trim((string)($_GET['status']??'')); $filter_type=trim((string)($_GET['type']??'')); $search=trim((string)($_GET['q']??''));
$where=['1=1'];$params=[];$types='';
if($filter_status!==''){$where[]='e.status=?';$params[]=$filter_status;$types.='s';}
if($filter_type!==''){$where[]='e.event_type=?';$params[]=$filter_type;$types.='s';}
if($search!==''){$where[]='(e.title LIKE ? OR e.location LIKE ? OR e.description LIKE ?)';$s='%'.$search.'%';array_push($params,$s,$s,$s);$types.='sss';}
$sql="SELECT e.*,(SELECT COUNT(*) FROM event_registrations r WHERE r.event_id=e.id) reg_count,(SELECT COUNT(*) FROM event_registrations r WHERE r.event_id=e.id AND r.attended=1) attended_count FROM events e WHERE ".implode(' AND ',$where)." ORDER BY e.event_date DESC,e.id DESC";
$stmt=$conn->prepare($sql); if($types!=='')$stmt->bind_param($types,...$params);$stmt->execute();$events=$stmt->get_result();
$stats=$conn->query("SELECT COUNT(*) total,COALESCE(SUM(status='upcoming'),0) upcoming,COALESCE(SUM(status='ongoing'),0) ongoing,COALESCE(SUM(status='completed'),0) completed,(SELECT COUNT(*) FROM event_registrations) total_regs FROM events")->fetch_assoc();
$event_types=['webinar'=>'Webinar','workshop'=>'Workshop','summit'=>'Summit','demo_day'=>'Demo Day','networking'=>'Networking','mentorship'=>'Mentorship'];
$event_statuses=['draft'=>'Draft','upcoming'=>'Upcoming','ongoing'=>'Ongoing','completed'=>'Completed','cancelled'=>'Cancelled'];
