<?php $has=false;while($ev=$events->fetch_assoc()):$has=true;$dt=!empty($ev['event_date'])?new DateTime((string)$ev['event_date']):null;$cap=(int)$ev['capacity'];$regs=(int)$ev['reg_count'];$pct=$cap>0?min(100,(int)round($regs/$cap*100)):0;$link=$base_site_url.'/register-event.php?event_id='.(int)$ev['id'];[$rclass,$rlabel,$ricon]=event_reminder_status($ev);?>
