d fa-pen"></i></button><form class="inline-form" method="post" action="includes/process-events.php" onsubmit="return confirm('Send this reminder now?')"><input type="hidden" name="csrf_token" value="<?=h($csrf)?>"><input type="hidden" name="action" value="send_reminders"><input type="hidden" name="id" value="<?=(int)$ev['id']?>"><button class="btn btn-sm btn-warning" title="Send now"><i class="fa-solid fa-bell"></i></button></form><form class="inline-form" method="post" action="includes/process-events.php" onsubmit="return confirm('Delete this event and all registrations?')"><input type="hidden" name="csrf_token" value="<?=h($csrf)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$ev['id']?>"><button class="btn btn-sm btn-danger" title="Delete"><i class="fa-solid fa-trash"></i></button></form><?php endif;?></div></td></tr>
