<?php if($can_manage_events):?><div class="modal-overlay" id="eventModal"><div class="modal"><div class="modal-header"><h3 id="eventModalTitle">Add Event</h3><button class="modal-close" type="button" onclick="closeEventModal()">&times;</button></div><form method="post" action="includes/process-events.php" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=h($csrf)?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="eventId"><input type="hidden" name="existing_cover" id="existingCover"><div class="modal-body"><div class="form-grid"><div class="form-group full"><label>Event title <span class="req">*</span></label><input class="form-control" name="title" id="eventTitle" required></div><div class="form-group"><label>Type</label><select class="form-control" name="event_type" id="eventType"><?php foreach($event_types as $k=>$v):?><option value="<?=h($k)?>"><?=h($v)?></option><?php endforeach;?></select></div><div class="form-group"><label>Status</label><select class="form-control" name="status" id="eventStatus"><?php foreach($event_statuses as $k=>$v):?><option value="<?=h($k)?>"><?=h($v)?></option><?php endforeach;?></select></div><div class="form-group"><label>Start date and time <span class="req">*</span></label><input class="form-control" type="datetime-local" name="event_date" id="eventDate" required></div><div class="form-group"><label>End date and time</label><input class="form-control" type="datetime-local" name="end_date" id="endDate"></div><div class="form-group"><label>Location</label><input class="form-control" name="location" id="eventLocation"></div><div class="form-group"><label>Meeting link</label><input class="form-control" type="url" name="meeting_link" id="meetingLink"></div><div class="form-group"><label>Capacity</label><input class="form-control" type="number" min="0" name="capacity" id="capacity" value="0"></div><div class="form-group"><label>Registration deadline</label><input class="form-control" type="datetime-local" name="registration_deadline" id="registrationDeadline"></div><div class="form-group full"><label>Description</label><textarea class="form-control" name="description" id="eventDescription"></textarea></div><div class="form-section"><div class="form-section-title">Automated reminder</div></div><div class="form-group"><label>Reminder period</label><select class="form-control" name="reminder_preset" id="reminderPreset" onchange="toggleReminderFields()"><option value="none">No reminder</option><option value="same_day">Same day</option><option value="1_day">1 day before</option><option value="2_days">2 days before</option><option value="3_days">3 days before</option><option value="7_days">7 days before</option><option value="14_days">14 days before</option><option value="custom">Custom period</option></select></div><div class="form-group"><label>Delivery method</label><select class="form-control" name="reminder_method" id="reminderMethod"><option value="email">Email</option><option value="notification">System notification</option><option value="both">Email and notification</option></select></div><div class="form-grid full conditional-fields" id="customReminderFields"><div class="form-group"><label>Reminder value</label><input class="form-control" type="number" min="0" name="reminder_value" id="reminderValue" value="1"></div><div class="form-group"><label>Reminder unit</label><select class="form-control" name="reminder_unit" id="reminderUnit"><option value="minutes">Minutes</option><option value="hours">Hours</option><option value="days">Days</option><option value="weeks">Weeks</option></select></div><div class="form-group"><label>Reminder time</label><input class="form-control" type="time" name="reminder_time" id="reminderTime" value="09:00"></div></div><div class="form-group full"><label class="form-check"><input type="checkbox" name="is_public" id="isPublic" value="1" checked><span>Allow public registration</span></label></div></div></div><div class="modal-footer"><button class="btn btn-secondary" type="button" onclick="closeEventModal()">Cancel</button><button class="btn btn-primary" type="submit"><i class="fa-solid fa-save"></i> Save Event</button></div></form></div></div><?php endif;?></main></div><div class="sidebar-overlay" id="sidebarOverlay"></div><script src="assets/js/admin.js"></script><script>
const eventModal=document.getElementById('eventModal');function localDate(v){return v?String(v).replace(' ','T').slice(0,16):''}function openEventModal(){document.getElementById('eventModalTitle').textContent='Add Event';eventModal.querySelector('form').reset();document.getElementById('eventId').value='';document.getElementById('reminderPreset').value='none';toggleReminderFields();eventModal.classList.add('open')}function closeEventModal(){eventModal.classList.remove('open')}function toggleReminderFields(){document.getElementById('customReminderFields').classList.toggle('is-visible',document.getElementById('reminderPreset').value==='custom')}function editEvent(e){openEventModal();document.getElementById('eventModalTitle').textContent='Edit Event';for(const [id,key] of Object.entries({eventId:'id',eventTitle:'title',eventType:'event_type',eventStatus:'status',eventLocation:'location',meetingLink:'meeting_link',capacity:'capacity',eventDescription:'description',existingCover:'cover_image',reminderMethod:'reminder_method',reminderValue:'reminder_value',reminderUnit:'reminder_unit',reminderTime:'reminder_time'})){const el=document.getElementById(id);if(el)el.value=e[key]??''}document.getElementById('eventDate').value=localDate(e.event_date);document.getElementById('endDate').value=localDate(e.end_date);document.getElementById('registrationDeadline').value=localDate(e.registration_deadline);document.getElementById('isPublic').checked=Number(e.is_public)===1;let preset='none';if(Number(e.reminder_enabled)===1){const v=Number(e.reminder_value),u=e.reminder_unit;if(v===0&&u==='days')preset='same_day';else if(u==='days'&&[1,2,3,7,14].includes(v))preset=v+'_'+(v===1?'day':'days');else preset='custom'}document.getElementById('reminderPreset').value=preset;toggleReminderFields()}eventModal?.addEventListener('click',e=>{if(e.target===eventModal)closeEventModal()});
</script></body></html>
